def activate_command(folder, system):
    if system == "windows":
        return folder + "\\Scripts\\activate"
    if system in ("mac", "linux"):
        return f"source {folder}/bin/activate"
    return None

import re

def parse_requirements(text):
    result = []
    for line in text.split("\n"):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        match = re.match(r"([A-Za-z0-9_.-]+)(.*)", line)
        result.append((match.group(1), match.group(2).strip()))
    return result

